rows = props.get("plans") or []
if isinstance(rows, str):
	try:
		rows = json.loads(rows)
	except Exception:
		rows = [line for line in rows.split("\n") if line.strip()]
if not isinstance(rows, list):
	rows = []



def escape(value):
	return str(value).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


def figure(value, escape):
	# a feature that ends in a figure ("Card fee 2.9% + 30¢") sets the figure in mono
	text = str(value)
	cut = -1
	for i in range(1, len(text)):
		if text[i].isdigit() and text[i - 1] == " ":
			cut = i
			break
	if cut <= 0 or text[0].isdigit():
		return escape(text)
	return escape(text[:cut]) + '<span class="lp-fig lrc-fig">' + escape(text[cut:]) + "</span>"


period = "yearly" if str(props.get("period") or "") == "yearly" else "monthly"
url = str(props.get("start_url") or "pricing#plans")
plans = []
for raw in rows:
	parts = [part.strip() for part in str(raw).split("|")]
	if not parts or not parts[0]:
		continue
	while len(parts) < 6:
		parts.append("")
	tag = parts[3]
	plans.append({
		"name": parts[0],
		"m": parts[1] or "$0",
		"y": parts[2] or parts[1] or "$0",
		"tag": tag,
		"has_tag": len(tag) > 0,
		"tag_show": "true" if tag else "false",
		"pick": "true" if tag else "false",
		"facts": parts[4],
		"features": [{"html": figure(f.strip(), escape)} for f in parts[4].split(";") if f.strip()],
		"cta": parts[5] or ("Start with " + parts[0]),
		"url": url,
		"hide_m": "true" if period == "yearly" else "false",
		"hide_y": "false" if period == "yearly" else "true",
	})
component.plans = plans
component.period = period
component.monthly_pressed = "false" if period == "yearly" else "true"
component.yearly_pressed = "true" if period == "yearly" else "false"
component.monthly_tab = "-1" if period == "yearly" else "0"
component.yearly_tab = "0" if period == "yearly" else "-1"
